CREATE SCHEMA IF NOT EXISTS meta;
CREATE TABLE IF NOT EXISTS meta.corep_schema_migrations (
    applied_order integer NOT NULL,
    path text PRIMARY KEY,
    sha256 char(64) NOT NULL,
    stage text NOT NULL,
    applied_at timestamptz NOT NULL DEFAULT now(),
    applied_by text NOT NULL DEFAULT current_user,
    CONSTRAINT ck_corep_schema_migrations_sha CHECK (sha256 ~ '^[0-9a-f]{64}$')
);
CREATE UNIQUE INDEX IF NOT EXISTS ux_corep_schema_migrations_order ON meta.corep_schema_migrations(applied_order);
